/*
  Urban Tech — home page enhancement
  This file is loaded by index.html. It also acts as a safe no-op replacement
  for the old jquery.stellar.min.js reference that was missing from the repo.
*/
(function () {
  "use strict";

  function initObjectCardImages() {
    var section = document.getElementById("objects");
    if (!section) return;

    var images = [
      "../assets/img/main/cards/object-residential.webp",
      "../assets/img/main/cards/object-offices.webp",
      "../assets/img/main/cards/object-retail-mall.webp",
      "../assets/img/main/cards/object-warehouses.webp",
      "../assets/img/main/cards/object-clinics.webp",
      "../assets/img/main/cards/object-industrial.webp"
    ];

    var cards = section.querySelectorAll(".ut-step-card");
    images.forEach(function (image, index) {
      if (!cards[index]) return;
      cards[index].style.setProperty("--ut-step-image", "url('" + image + "')");
    });
  }

  function initWhyUrbanTechStepCards() {
    var section = document.getElementById("why-us");
    if (!section) return;

    var sectionLead = section.querySelector(".section-head p");
    if (sectionLead) {
      sectionLead.innerHTML = "Ми поєднуємо електрику, слаботочку, безпеку та автоматизацію в одну зрозумілу систему — щоб об’єкт був готовий до стабільної роботи сьогодні й до розвитку в майбутньому.";
    }

    var grid = section.querySelector(".ut-why-grid");
    if (!grid) return;

    grid.className = "row g-4 ut-step-card-row ut-why-step-card-row";
    grid.setAttribute("aria-label", "Переваги Urban Tech");

    grid.innerHTML = [
      {
        number: "01",
        icon: "bi-cpu",
        title: "Технічна логіка",
        image: "../assets/img/main/cards/why-technical-logic.webp",
        text: "Продумуємо навантаження, групи ліній, резерв, доступ до обслуговування та можливість майбутнього розширення."
      },
      {
        number: "02",
        icon: "bi-diagram-3",
        title: "Комплексний підхід",
        image: "../assets/img/main/cards/why-complex-approach.webp",
        text: "Електрика, відео, охорона, СКУД, Wi-Fi, автоматизація та резервне живлення — в одній технічній логіці."
      },
      {
        number: "03",
        icon: "bi-tools",
        title: "Акуратна реалізація",
        image: "../assets/img/main/cards/why-neat-execution.webp",
        text: "Монтуємо охайно, маркуємо лінії, дотримуємось структури та робимо систему зрозумілою для подальшого обслуговування."
      }
    ].map(function (card) {
      return [
        '<div class="col-12 col-md-6 col-lg-4">',
        '  <article class="card h-100 ut-step-card" style="--ut-step-image: url(\'' + card.image + '\');" aria-label="' + card.title + '">',
        '    <div class="card-body ut-step-card__body">',
        '      <div class="ut-step-card__top">',
        '        <div class="ut-step-card__icon"><i class="bi ' + card.icon + '"></i></div>',
        '        <span class="ut-step-card__number">' + card.number + '</span>',
        '      </div>',
        '      <h3 class="ut-step-card__title">' + card.title + '</h3>',
        '      <p class="ut-step-card__text mb-0">' + card.text + '</p>',
        '    </div>',
        '  </article>',
        '</div>'
      ].join("\n");
    }).join("\n\n");
  }

  function initHomeEnhancements() {
    initObjectCardImages();
    initWhyUrbanTechStepCards();
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", initHomeEnhancements, { once: true });
  } else {
    initHomeEnhancements();
  }
})();